import {EXPANDED_STORIES,storyFor} from './dialogue-expansion.js';
import {MORE_OPENINGS,STAFF_SCENES,STAFF_ANSWERS,NEW_STORIES} from './everyday-life.js';
// Authored school-life scripts with contextual slots, not external chat generation.
export const TOPICS={learning:'수업과 배움',friends:'친구 관계',interests:'좋아하는 활동',autonomy:'우리 반의 약속',followup:'지난 이야기 이어가기',daily:'오늘의 작은 발견',supplies:'준비물과 부탁',feelings:'오늘의 마음',roles:'내가 맡은 역할'};
const OPENINGS={learning:['{weak}에서 어디까지 알았는지는 설명할 수 있어요. 다음 단계가 어려워요.','{strong}는 해 보고 싶은데 {weak}에서 틀릴까 봐 시작을 망설였어요.','어제와 다른 풀이를 생각했어요. 답보다 방법을 먼저 봐 주실래요?'],friends:['{friend}와 같은 역할을 하고 싶어요. 둘 다 할 수 있는 방법이 있을까요?','친구가 혼자 있고 싶다는데, 같이 놀자고 다시 물어봐도 될까요?','모둠에서 제 말이 끝나기 전에 다음 이야기로 넘어갔어요.'],interests:['{strong} 시간에 해 본 것을 더 해 보고 싶어요.','아직 잘하는 건 아니지만, 새로운 활동을 맡아 보고 싶어요.','좋아하는 책을 친구들에게 소개할 방법을 생각했어요.'],autonomy:['우리 반 약속을 학생들 말로 다시 써 보면 어떨까요?','약속을 지키지 못했을 때 다시 해 볼 기회도 있었으면 좋겠어요.','모두 같은 방법으로 해야 하는지 궁금해요. 다른 방법을 골라도 되나요?'],followup:['지난번 함께 정한 방법을 해 봤어요. 잘된 부분부터 이야기할게요.','그때 약속한 걸 기억하고 있어요. 아직 막힌 부분도 있어요.','지난번과 비슷한 일이 있었는데 이번에는 제가 먼저 말했어요.'],daily:['등교하면서 창밖의 달을 봤어요. 낮에도 보일 수 있나요?','오늘 먼저 인사하고 싶었는데 쑥스러워서 손만 흔들었어요.','책상 밑에서 이름표를 찾았어요. 누구 것인지 같이 확인할까요?'],supplies:['연필심이 부러졌어요. 공용 연필을 빌린 뒤 제자리에 돌려둘게요.','활동지가 한 장 부족해요. 기다리는 동안 무엇을 하면 될까요?','가져온 준비물이 안내와 조금 달라요. 이것으로 해도 될까요?'],feelings:['오늘은 조금 조용히 있고 싶어요. 나중에 이야기해도 될까요?','발표는 해 보고 싶은데 앞에 서면 말이 짧아져요.','처음에는 속상했는데 친구 말을 들으니 생각이 조금 달라졌어요.'],roles:['{role}을 맡았는데 어디까지 하면 되는지 함께 확인하고 싶어요.','오늘 제 역할에 도움이 필요해요. 혼자 끝내려고 하니 시간이 모자라요.','다음에는 다른 역할도 해 보고 싶어요. 친구와 바꾸어도 될까요?']};
const ACTIONS={learning:['어디까지 이해했는지 보여 주기','첫 단계부터 한 번 더 해 보기','다른 풀이와 나란히 비교하기'],friends:['상대가 어떤 마음인지 먼저 물어보기','역할을 번갈아 맡는 방법 제안하기','한 사람씩 말할 시간을 정하기'],interests:['작은 예시를 준비해 보기','친구에게 설명할 그림 만들기','다음 활동에서 맡을 역할 고르기'],autonomy:['모두의 의견을 한 줄씩 모으기','지키기 어려운 부분을 바꾸어 보기','다시 시도할 방법을 약속에 넣기'],followup:['지난 방법에서 잘된 부분 남기기','어려웠던 단계만 바꾸어 보기','다음 확인 날짜를 정해 두기'],daily:['관찰한 모습을 그림으로 남기기','궁금한 점을 질문함에 적기','친구와 함께 확인해 보기'],supplies:['공용 도구를 빌리고 반납하기','지금 가진 재료로 가능한 방법 찾기','다음 준비물을 그림으로 확인하기'],feelings:['지금 편한 참여 방법 고르기','짝과 먼저 연습해 보기','이야기를 이어갈 시간을 정하기'],roles:['역할의 범위를 함께 확인하기','도움이 필요한 부분을 나누기','친구와 역할 교환을 의논하기']};
const STAFF_TASKS={colleague:['학년회의의 학생 관찰 안건','다음 주 모둠 활동 자료','공동 수업 준비 순서'],principal:['학생 지원의 우선순위','교사 일정이 겹치는 부분','업무별 학기 초 계획'],admin:['물품 구입 목록과 재고','수리할 시설의 상태','교실에 물품을 전달할 시간'],librarian:['학년에 맞는 읽기 분량','온책읽기 후 표현 활동','학급 도서 대출 일정'],neulbom:['남는 학생의 다음 일정','귀가 방법이 바뀐 학생 인계','교실에 두고 간 물건 확인'],specialist:['전담수업에서 보인 참여 모습','다음 차시 준비물','학생에게 잘 맞았던 안내 방법']};
for(const [topic,lines] of Object.entries(MORE_OPENINGS))OPENINGS[topic].push(...lines);
export function script(state,p,topic,index){const specialist=staffScript(state,p,topic,index);if(specialist)return specialist;if(p.kind==='student'){const expanded=storyFor(state,p,topic,index);if(expanded)return expanded;}const fill=t=>t.replace(/\{(weak|strong|friend|role)\}/g,(_,key)=>({weak:p.weak?.[0],strong:p.strong?.[0],friend:state.students.find(s=>s.id===p.friend)?.name,role:p.role}[key]||'우리 반 활동'));const a=(ACTIONS[topic]||ACTIONS.daily),which=index%3;let opening;
 if(p.kind==='student'){opening=fill((OPENINGS[topic]||OPENINGS.daily)[index%(OPENINGS[topic]||OPENINGS.daily).length]);if(topic==='followup'&&p.memories?.[0])opening+=' '+p.memories[0].text;if(state.config.grade<=2)opening+=' 처음에는 같이 해 주세요.';if(state.config.grade>=5&&['autonomy','roles'].includes(topic))opening+=' 우리가 정할 수 있는 범위도 알려 주세요.';}
 else if(p.kind==='parent'){const focus=state.config.grade<=2?'등교 준비와 학교 적응':state.config.grade>=5?'자율적인 학습과 친구 관계':'학습 습관과 친구 관계';opening=[`${p.child.name}의 ${focus}를 함께 살펴보고 싶어요. 가정에서 본 모습부터 말씀드릴까요?`,`요즘 ${p.child.name}가 ${p.child.strong[0]} 이야기를 자주 해요. 학교에서 직접 보신 모습이 궁금합니다.`,`지난번 안내를 집에서 해 보았어요. 다음에는 어떤 점을 함께 확인하면 좋을까요?`,`집에서는 혼자 해 보겠다고 하는 일이 늘었어요. 학교에서도 스스로 고를 수 있는 활동이 있나요?`,`준비물 안내를 아이와 같이 읽어 봤어요. 아이가 직접 챙길 부분부터 정해 보려고요.`,`아이가 학교에서 있었던 일을 짧게만 말하는 날도 있어요. 지금 확인이 필요한 변화가 있는지 함께 듣고 싶습니다.`][index%6];}
 else opening=index%6>=3?(STAFF_SCENES[p.id]||STAFF_SCENES.colleague)[which]:(STAFF_TASKS[p.id]||STAFF_TASKS.colleague)[which]+'부터 함께 확인할까요? 지금 확인된 것과 아직 필요한 것을 나누어 이야기해요.';
 const student=p.kind==='student';return {opening,choices:student?[[`어떤 장면이었는지 조금 더 들려줄래?`,`${a[which]}부터 함께 생각해 보자.`,`지금 필요한 도움을 네가 골라 볼래?`],[`${a[(which+1)%3]}는 어떨까?`,`네 방법을 먼저 해 보고 다시 이야기하자.`,`약속을 메모하고 다음에 이어서 보자.`]]:[['직접 확인한 사실부터 나누겠습니다.','필요한 도움과 역할을 함께 정할까요?','가능한 시간과 다음 확인 일을 맞춰 보겠습니다.'],['학교톡과 개인 일정에 확인할 일을 남기겠습니다.','자료를 준비한 뒤 다시 의견을 부탁드리겠습니다.','함께 정한 방법을 적용하고 변화를 나누겠습니다.']],answers:student?[[fill(`제 생각을 다 말해도 된다고 하니 조금 편해졌어요. ${a[which]}부터 설명할게요.`),`${a[which]}부터 하면 시작할 수 있을 것 같아요.`,`${a[(which+2)%3]}를 먼저 골라 볼래요. 도움은 막힌 부분에서 부탁할게요.`],[`${a[(which+1)%3]}를 해 보니 처음과 생각이 달라졌어요.`,`제가 고른 방법으로 해 보고, 잘된 점과 어려운 점을 다시 말할게요.`,`약속을 기억해 둘게요. 다음에는 제가 해 본 이야기를 가지고 올게요.`]]:[[p.kind==='parent'?'가정과 학교에서 본 장면을 나누니 확인할 점이 분명해지네요.':STAFF_ANSWERS[p.id]||STAFF_ANSWERS.colleague,'담당할 부분을 나누면 혼자 해결하려고 서두르지 않아도 되겠어요.','좋습니다. 겹치는 일정을 살피고 약속한 때에 다시 확인해요.'],['정리한 내용을 확인하겠습니다. 새로운 연락이 오면 일정도 함께 보겠습니다.','자료에서 궁금한 부분을 표시해 두고 다시 이야기 나누겠습니다.','변화가 생기면 구체적인 장면과 함께 알려 주세요. 다음 방법을 함께 조정해요.']]};}
